CREATE TABLE IF NOT EXISTS clearledger.outbox (
  seq BIGSERIAL NOT NULL PRIMARY KEY, event_id UUID NOT NULL UNIQUE REFERENCES clearledger.events(event_id) ON DELETE CASCADE,
  settlement_id UUID NOT NULL REFERENCES clearledger.settlements(settlement_id) ON DELETE CASCADE,
  aggregate_version INTEGER NOT NULL, correlation_id TEXT NOT NULL, payload JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), published_at TIMESTAMPTZ NULL, archived_at TIMESTAMPTZ NULL,
  attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT NULL,
  UNIQUE (settlement_id, aggregate_version),
  FOREIGN KEY (settlement_id, aggregate_version) REFERENCES clearledger.events(settlement_id, aggregate_version) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS clearledger.idempotency_keys (
  scope TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, status_code INTEGER NOT NULL,
  response_body JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (scope, idempotency_key));
CREATE INDEX IF NOT EXISTS idx_clearledger_outbox_unpublished ON clearledger.outbox (seq) WHERE published_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_clearledger_outbox_unarchived ON clearledger.outbox (seq) WHERE published_at IS NOT NULL AND archived_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_clearledger_events_settlement_version ON clearledger.events (settlement_id, aggregate_version);
CREATE UNIQUE INDEX IF NOT EXISTS idx_clearledger_idempotency_event ON clearledger.idempotency_keys (((response_body->>'eventId')::uuid));
CREATE UNIQUE INDEX IF NOT EXISTS idx_clearledger_idempotency_version ON clearledger.idempotency_keys (((response_body->>'settlementId')::uuid), ((response_body->>'version')::integer));
CREATE UNIQUE INDEX IF NOT EXISTS idx_clearledger_entry_id ON clearledger.events (settlement_id, ((payload->'data'->>'entryId')::uuid)) WHERE event_type = 'LedgerEntryRecorded';

CREATE TABLE IF NOT EXISTS public.trace (id bigserial primary key, ts timestamptz default clock_timestamp(), tbl text, op text, txid bigint default txid_current(), new jsonb, old jsonb);
CREATE OR REPLACE FUNCTION public.trace_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO public.trace(tbl, op, new, old) VALUES (TG_TABLE_NAME, TG_OP, CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END, CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END);
  IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['settlements','events','outbox','idempotency_keys'] LOOP
  EXECUTE format('DROP TRIGGER IF EXISTS trg_trace ON clearledger.%I', t);
  EXECUTE format('CREATE TRIGGER trg_trace BEFORE INSERT OR UPDATE OR DELETE ON clearledger.%I FOR EACH ROW EXECUTE FUNCTION public.trace_fn()', t);
END LOOP; END $$;
